const ld = require('lodash');
let responseData;
const contentType = pm.response.headers.get('Content-Type');
if (contentType === "application/xml") {
  var parseString = require('xml2js').parseString;
  parseString(pm.response.body, function(err, result) {
    if (err) {
      console.error('Error parsing XML:', err);
    } else {
      responseData = result;
    }
  });
} else {
  responseData = pm.response.json();
}
// Status code check with early exit
const expectedStatusCode = parseInt(pm.variables.get("statusCode"));
let statusMatches = true;
if (pm.variables.get("statusCode")) {
  statusMatches = (pm.response.code === expectedStatusCode);
  pm.test("Status code matches expected value", function() {
    pm.expect(pm.response.code).to.equal(expectedStatusCode);
  });
}

if (pm.response.code == 201 && statusMatches) {
  pm.test("Resource created successfully", function() {
    pm.expect(pm.response.status).to.be.eql("Created");
    try {
      if (responseData !== null && responseData !== undefined) {
        {
          // Condition: Raw data type and parent property is not an array
          // pathStr: responseData
          // subKey: id
          // required: []
          let requiredField = false
          if (requiredField || ld.get(responseData, 'id')) {
            pm.test(`'responseData field has id that is of type string'`, function() {
              let parent = responseData;
              if (pm.expect(parent).to.have.nested.property(`id`)) {
                const value = responseData?.id;

                if (!ld.isEmpty(value)) {
                  pm.expect(typeof value).to.equal("string");
                }
              }
            })

          }
        }
      }
    } catch (error) {
      console.error('Error during response validation:', error.message);
    }
  });

}
if (pm.response.code == 400 && statusMatches) {
  pm.test("Bad Request", function() {
    pm.expect(pm.response.status).to.be.eql("Bad Request");
  });

}
if (pm.response.code == 500 && statusMatches) {
  pm.test("Internal Server Error", function() {
    pm.expect(pm.response.status).to.be.eql("Internal Server Error");
  });

}

